CREATE TABLE IF NOT EXISTS places(id INTEGER PRIMARY KEY AUTOINCREMENT, osm TEXT NOT NULL UNIQUE, name TEXT NOT NULL, display TEXT NOT NULL, lat REAL NOT NULL, lon REAL NOT NULL, feat TEXT, created TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS districts(n INTEGER PRIMARY KEY, place_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS geo_cache(q TEXT PRIMARY KEY, res TEXT NOT NULL, created TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS friends(a INTEGER NOT NULL, b INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','ok')), created TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(a,b));
CREATE TABLE IF NOT EXISTS invites(id INTEGER PRIMARY KEY AUTOINCREMENT, from_id INTEGER NOT NULL, to_id INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('house','room')), ref TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS presence(user_id INTEGER PRIMARY KEY, seen INTEGER NOT NULL, st TEXT NOT NULL DEFAULT 'idle', district INTEGER);
CREATE INDEX IF NOT EXISTS friends_b ON friends(b);
CREATE INDEX IF NOT EXISTS invites_to ON invites(to_id, seen);
